* {
  box-sizing: border-box;
}

html,
body {
  margin: 0;
  min-width: 0;
  background: var(--viz-bg);
  color: var(--viz-text);
  font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
}

body {
  min-height: 100vh;
}

button,
input {
  font: inherit;
}

#app {
  width: min(920px, 100%);
  margin: 0 auto;
  padding: 18px 22px 22px;
  background: var(--viz-bg);
  color: var(--viz-text);
}

.topbar {
  min-height: 44px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  margin-bottom: 12px;
}

h1 {
  min-width: 0;
  margin: 0;
  color: var(--viz-text);
  font-size: clamp(1.15rem, 2.4vw, 1.55rem);
  font-weight: 680;
  line-height: 1.2;
  letter-spacing: -0.018em;
}

.playback {
  display: flex;
  flex: 0 0 auto;
  gap: 8px;
}

.icon-button {
  width: 38px;
  height: 38px;
  padding: 9px;
  display: grid;
  place-items: center;
  border: 1px solid var(--viz-line);
  border-radius: 50%;
  background: var(--viz-control);
  color: var(--viz-text);
  cursor: pointer;
}

.icon-button:hover {
  background: var(--viz-control-hover);
}

.icon-button:focus-visible,
#scene:focus-visible,
input[type="range"]:focus-visible {
  outline: 2px solid var(--viz-accent);
  outline-offset: 2px;
}

.icon-button svg {
  width: 18px;
  height: 18px;
  display: block;
  color: currentColor;
}

[hidden] {
  display: none !important;
}

#scene {
  display: block;
  width: 100%;
  height: clamp(360px, 53vw, 470px);
  border: 1px solid var(--viz-line);
  border-radius: 12px;
  background: var(--viz-panel);
  color: var(--viz-text);
  cursor: grab;
  touch-action: none;
}

#scene.dragging {
  cursor: grabbing;
}

.result-strip {
  min-height: 58px;
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  border-bottom: 1px solid var(--viz-line);
  background: var(--viz-bg);
}

.result-item {
  min-width: 0;
  padding: 10px 14px;
  display: flex;
  flex-direction: column;
  justify-content: center;
  gap: 3px;
}

.result-item + .result-item {
  border-left: 1px solid var(--viz-line);
}

.result-item span {
  color: var(--viz-muted);
  font-size: 0.72rem;
  line-height: 1.1;
}

.result-item output,
.control output {
  color: var(--viz-accent);
  font-family: ui-monospace, SFMono-Regular, Consolas, "Liberation Mono", monospace;
  font-variant-numeric: tabular-nums;
}

.result-item output {
  overflow: hidden;
  font-size: 0.94rem;
  font-weight: 650;
  line-height: 1.2;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.controls {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 24px;
  padding-top: 18px;
}

.control {
  min-width: 0;
}

.control-row {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 10px;
  margin-bottom: 10px;
}

.control label {
  color: var(--viz-text);
  font-size: 0.84rem;
  font-weight: 620;
}

.control output {
  flex: 0 0 auto;
  font-size: 0.79rem;
}

input[type="range"] {
  width: 100%;
  height: 20px;
  margin: 0;
  appearance: none;
  -webkit-appearance: none;
  background: transparent;
  cursor: pointer;
}

input[type="range"]::-webkit-slider-runnable-track {
  height: 4px;
  border-radius: 2px;
  background: var(--viz-line);
}

input[type="range"]::-webkit-slider-thumb {
  width: 16px;
  height: 16px;
  margin-top: -6px;
  appearance: none;
  -webkit-appearance: none;
  border: 2px solid var(--viz-panel);
  border-radius: 50%;
  background: var(--viz-accent);
}

input[type="range"]::-moz-range-track {
  height: 4px;
  border: 0;
  border-radius: 2px;
  background: var(--viz-line);
}

input[type="range"]::-moz-range-thumb {
  width: 14px;
  height: 14px;
  border: 2px solid var(--viz-panel);
  border-radius: 50%;
  background: var(--viz-accent);
}

.range-ends {
  display: flex;
  justify-content: space-between;
  gap: 8px;
  margin-top: 2px;
  color: var(--viz-muted);
  font-family: ui-monospace, SFMono-Regular, Consolas, "Liberation Mono", monospace;
  font-size: 0.64rem;
  font-variant-numeric: tabular-nums;
}

.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

@media (max-width: 620px) {
  #app {
    padding: 14px 14px 18px;
  }

  .topbar {
    margin-bottom: 10px;
  }

  #scene {
    height: 360px;
  }

  .result-item {
    padding: 9px 7px;
  }

  .result-item span {
    font-size: 0.65rem;
  }

  .result-item output {
    font-size: 0.8rem;
  }

  .controls {
    grid-template-columns: 1fr;
    gap: 13px;
    padding-top: 14px;
  }

  .control-row {
    margin-bottom: 5px;
  }
}

