"use strict";

const COULOMB_CONSTANT = 8.9875517923e9;
const MIN_DISTANCE = 0.2;
const MAX_DISTANCE = 2;
const DISTANCE_STEP = 0.05;
const INITIAL_STATE = Object.freeze({ q1: 4, q2: -6, distance: 0.8 });

const app = document.getElementById("app");
const canvas = document.getElementById("scene");
const context = canvas.getContext("2d");
const q1Input = document.getElementById("q1");
const q2Input = document.getElementById("q2");
const distanceInput = document.getElementById("distance");
const q1Value = document.getElementById("q1Value");
const q2Value = document.getElementById("q2Value");
const distanceValue = document.getElementById("distanceValue");
const forceOutput = document.getElementById("forceOutput");
const interactionOutput = document.getElementById("interactionOutput");
const distanceOutput = document.getElementById("distanceOutput");
const playPause = document.getElementById("playPause");
const playIcon = document.getElementById("playIcon");
const pauseIcon = document.getElementById("pauseIcon");
const resetButton = document.getElementById("resetButton");
const liveStatus = document.getElementById("liveStatus");
const reducedMotion = window.matchMedia("(prefers-reduced-motion: reduce)");

const state = {
  q1: INITIAL_STATE.q1,
  q2: INITIAL_STATE.q2,
  distance: INITIAL_STATE.distance,
  running: !reducedMotion.matches,
  phase: 0,
  dragging: null,
  pointerId: null
};

let cssWidth = 0;
let cssHeight = 0;
let pixelRatio = 1;
let frameRequest = null;
let previousFrameTime = null;
let palette = {};

function clamp(value, minimum, maximum) {
  return Math.min(maximum, Math.max(minimum, value));
}

function readPalette() {
  const styles = getComputedStyle(app);
  palette = {
    background: styles.getPropertyValue("--viz-bg").trim(),
    panel: styles.getPropertyValue("--viz-panel").trim(),
    control: styles.getPropertyValue("--viz-control").trim(),
    text: styles.getPropertyValue("--viz-text").trim(),
    muted: styles.getPropertyValue("--viz-muted").trim(),
    line: styles.getPropertyValue("--viz-line").trim(),
    accent: styles.getPropertyValue("--viz-accent").trim(),
    accentText: styles.getPropertyValue("--viz-accent-text").trim()
  };
}

function chargeText(value) {
  if (value > 0) return `+${value} µC`;
  if (value < 0) return `−${Math.abs(value)} µC`;
  return "0 µC";
}

function forceMagnitude() {
  const q1Coulombs = state.q1 * 1e-6;
  const q2Coulombs = state.q2 * 1e-6;
  return COULOMB_CONSTANT * Math.abs(q1Coulombs * q2Coulombs) / (state.distance * state.distance);
}

function forceText(force) {
  if (force === 0) return "0 N";
  if (force >= 10) return `${force.toFixed(1)} N`;
  if (force >= 1) return `${force.toFixed(2)} N`;
  if (force >= 0.1) return `${force.toFixed(3)} N`;
  if (force >= 0.01) return `${force.toFixed(4)} N`;
  return `${force.toFixed(5)} N`;
}

function interactionType() {
  const product = state.q1 * state.q2;
  if (product === 0) return "No force";
  return product < 0 ? "Attraction" : "Repulsion";
}

function distanceText() {
  return `${state.distance.toFixed(2)} m`;
}

function describeScene() {
  const interaction = interactionType();
  const force = forceText(forceMagnitude());
  const direction = interaction === "Attraction"
    ? "The equal and opposite force arrows point toward the other charge."
    : interaction === "Repulsion"
      ? "The equal and opposite force arrows point away from the other charge."
      : "No force arrows are shown because one charge is zero.";
  return `Charge one is ${chargeText(state.q1)}, charge two is ${chargeText(state.q2)}, and their separation is ${distanceText()}. The interaction is ${interaction.toLowerCase()} with force magnitude ${force}. ${direction}`;
}

function announce(prefix) {
  liveStatus.textContent = `${prefix} ${describeScene()}`.trim();
}

function syncOutputs(shouldAnnounce, prefix) {
  const force = forceMagnitude();
  const interaction = interactionType();

  q1Input.value = String(state.q1);
  q2Input.value = String(state.q2);
  distanceInput.value = String(state.distance);
  q1Value.textContent = chargeText(state.q1);
  q2Value.textContent = chargeText(state.q2);
  distanceValue.textContent = distanceText();
  forceOutput.textContent = forceText(force);
  interactionOutput.textContent = interaction;
  distanceOutput.textContent = distanceText();
  canvas.setAttribute("aria-label", describeScene());

  if (shouldAnnounce) announce(prefix || "Updated.");
  draw();
}

function updatePlaybackButton() {
  playIcon.hidden = state.running;
  pauseIcon.hidden = !state.running;
  playPause.setAttribute("aria-pressed", String(state.running));
  playPause.setAttribute(
    "aria-label",
    state.running ? "Pause force-direction animation" : "Play force-direction animation"
  );
}

function startAnimation() {
  if (!state.running || document.hidden || frameRequest !== null) return;
  previousFrameTime = null;
  frameRequest = requestAnimationFrame(animate);
}

function stopAnimation() {
  if (frameRequest !== null) cancelAnimationFrame(frameRequest);
  frameRequest = null;
  previousFrameTime = null;
}

function setRunning(running, shouldAnnounce) {
  state.running = running;
  updatePlaybackButton();
  if (state.running) startAnimation();
  else stopAnimation();
  draw();
  if (shouldAnnounce) liveStatus.textContent = running ? "Force-direction animation playing." : "Force-direction animation paused.";
}

function animate(time) {
  frameRequest = null;
  if (!state.running || document.hidden) return;
  if (previousFrameTime !== null) {
    state.phase = (state.phase + (time - previousFrameTime) / 1500) % 1;
  }
  previousFrameTime = time;
  draw();
  frameRequest = requestAnimationFrame(animate);
}

function geometry() {
  const radius = clamp(cssWidth * 0.038, 25, 32);
  const sideRoom = radius + 28;
  const maximumSeparation = Math.max(168, cssWidth - sideRoom * 2);
  const minimumSeparation = Math.min(132, maximumSeparation - 34);
  const fraction = (state.distance - MIN_DISTANCE) / (MAX_DISTANCE - MIN_DISTANCE);
  const separation = minimumSeparation + fraction * (maximumSeparation - minimumSeparation);
  const centerX = cssWidth / 2;
  const centerY = Math.max(150, Math.min(cssHeight * 0.49, cssHeight - 130));

  return {
    radius,
    minimumSeparation,
    maximumSeparation,
    separation,
    centerX,
    centerY,
    charge1: { x: centerX - separation / 2, y: centerY },
    charge2: { x: centerX + separation / 2, y: centerY },
    bracketY: centerY + radius + 58
  };
}

function drawArrow(startX, y, direction, length, label) {
  const endX = startX + direction * length;
  const headLength = 9;
  const headWidth = 5.5;

  context.save();
  context.strokeStyle = palette.accent;
  context.fillStyle = palette.accent;
  context.lineWidth = 3;
  context.lineCap = "round";
  context.lineJoin = "round";

  context.beginPath();
  context.moveTo(startX, y);
  context.lineTo(endX, y);
  context.stroke();

  context.beginPath();
  context.moveTo(endX, y);
  context.lineTo(endX - direction * headLength, y - headWidth);
  context.lineTo(endX - direction * headLength, y + headWidth);
  context.closePath();
  context.fill();

  const markerProgress = 0.18 + state.phase * 0.64;
  const markerX = startX + direction * length * markerProgress;
  context.beginPath();
  context.arc(markerX, y, 4, 0, Math.PI * 2);
  context.fillStyle = palette.panel;
  context.fill();
  context.lineWidth = 2;
  context.strokeStyle = palette.accent;
  context.stroke();

  context.fillStyle = palette.accent;
  context.font = "650 12px ui-monospace, SFMono-Regular, Consolas, monospace";
  context.textAlign = "center";
  context.textBaseline = "bottom";
  context.fillText(label, startX + direction * length * 0.52, y - 9);
  context.restore();
}

function drawCharge(charge, value, index, radius) {
  const isPositive = value > 0;
  const isNegative = value < 0;

  context.save();
  context.beginPath();
  context.arc(charge.x, charge.y, radius, 0, Math.PI * 2);
  context.fillStyle = isPositive ? palette.accent : isNegative ? palette.panel : palette.control;
  context.fill();
  context.lineWidth = isNegative ? 3 : 2;
  context.strokeStyle = isPositive ? palette.accent : isNegative ? palette.accent : palette.line;
  context.stroke();

  context.fillStyle = isPositive ? palette.accentText : isNegative ? palette.accent : palette.muted;
  context.font = `700 ${Math.round(radius * 0.92)}px ui-sans-serif, system-ui, sans-serif`;
  context.textAlign = "center";
  context.textBaseline = "middle";
  context.fillText(isPositive ? "+" : isNegative ? "−" : "0", charge.x, charge.y - 1);

  context.fillStyle = palette.text;
  context.font = "600 13px ui-monospace, SFMono-Regular, Consolas, monospace";
  context.textBaseline = "top";
  context.fillText(`q${index === 1 ? "₁" : "₂"}  ${chargeText(value)}`, charge.x, charge.y + radius + 13);
  context.restore();
}

function drawSeparationBracket(layout) {
  const leftX = layout.charge1.x;
  const rightX = layout.charge2.x;
  const y = layout.bracketY;
  const label = `r = ${distanceText()}`;

  context.save();
  context.strokeStyle = palette.line;
  context.lineWidth = 1.5;
  context.setLineDash([]);
  context.beginPath();
  context.moveTo(leftX, y - 7);
  context.lineTo(leftX, y + 7);
  context.moveTo(leftX, y);
  context.lineTo(rightX, y);
  context.moveTo(rightX, y - 7);
  context.lineTo(rightX, y + 7);
  context.stroke();

  context.font = "600 12px ui-monospace, SFMono-Regular, Consolas, monospace";
  const labelWidth = context.measureText(label).width + 16;
  context.fillStyle = palette.panel;
  context.fillRect(layout.centerX - labelWidth / 2, y - 10, labelWidth, 20);
  context.fillStyle = palette.accent;
  context.textAlign = "center";
  context.textBaseline = "middle";
  context.fillText(label, layout.centerX, y);
  context.restore();
}

function drawForceVectors(layout, force) {
  if (force === 0) {
    context.save();
    context.fillStyle = palette.muted;
    context.font = "600 13px ui-monospace, SFMono-Regular, Consolas, monospace";
    context.textAlign = "center";
    context.textBaseline = "bottom";
    context.fillText("F = 0", layout.centerX, layout.centerY - layout.radius - 18);
    context.restore();
    return;
  }

  const attraction = state.q1 * state.q2 < 0;
  const maximumForce = COULOMB_CONSTANT * (10e-6 * 10e-6) / (MIN_DISTANCE * MIN_DISTANCE);
  const strength = Math.log1p(force) / Math.log1p(maximumForce);
  const idealLength = 36 + 84 * strength;
  let availableLength;

  if (attraction) {
    const innerGap = layout.separation - layout.radius * 2;
    availableLength = Math.max(18, innerGap / 2 - 8);
  } else {
    const leftRoom = layout.charge1.x - layout.radius - 16;
    const rightRoom = cssWidth - layout.charge2.x - layout.radius - 16;
    availableLength = Math.max(16, Math.min(leftRoom, rightRoom));
  }

  const length = Math.min(idealLength, availableLength);
  const direction1 = attraction ? 1 : -1;
  const direction2 = attraction ? -1 : 1;
  const start1 = layout.charge1.x + direction1 * layout.radius;
  const start2 = layout.charge2.x + direction2 * layout.radius;

  drawArrow(start1, layout.centerY, direction1, length, "F₁");
  drawArrow(start2, layout.centerY, direction2, length, "F₂");
}

function draw() {
  if (!cssWidth || !cssHeight || !palette.panel) return;

  const layout = geometry();
  const force = forceMagnitude();
  context.clearRect(0, 0, cssWidth, cssHeight);
  context.fillStyle = palette.panel;
  context.fillRect(0, 0, cssWidth, cssHeight);

  context.save();
  context.fillStyle = palette.text;
  context.font = `${cssWidth < 520 ? "650 16px" : "650 18px"} ui-monospace, SFMono-Regular, Consolas, monospace`;
  context.textAlign = "left";
  context.textBaseline = "top";
  context.fillText("F = k |q₁q₂| / r²", 20, 20);

  context.fillStyle = palette.muted;
  context.font = "12px ui-monospace, SFMono-Regular, Consolas, monospace";
  context.fillText("k = 8.99 × 10⁹ N·m²/C²", 20, 47);

  if (cssWidth >= 610) {
    context.textAlign = "right";
    context.fillText("same sign repels · opposite signs attract", cssWidth - 20, 24);
  }
  context.restore();

  context.save();
  context.strokeStyle = palette.line;
  context.lineWidth = 1.5;
  context.setLineDash([5, 7]);
  context.beginPath();
  context.moveTo(layout.charge1.x, layout.centerY);
  context.lineTo(layout.charge2.x, layout.centerY);
  context.stroke();
  context.restore();

  drawForceVectors(layout, force);
  drawCharge(layout.charge1, state.q1, 1, layout.radius);
  drawCharge(layout.charge2, state.q2, 2, layout.radius);
  drawSeparationBracket(layout);

  context.save();
  context.fillStyle = palette.muted;
  context.font = `${cssWidth < 520 ? "11px" : "12px"} ui-sans-serif, system-ui, sans-serif`;
  context.textBaseline = "alphabetic";
  context.textAlign = "left";
  context.fillText("Drag a charge to change r", 20, cssHeight - 18);
  if (cssWidth >= 520) {
    context.textAlign = "right";
    context.fillText("Arrow length is compressed for readability", cssWidth - 20, cssHeight - 18);
  }
  context.restore();
}

function resizeCanvas() {
  const bounds = canvas.getBoundingClientRect();
  if (bounds.width <= 0 || bounds.height <= 0) return;

  cssWidth = bounds.width;
  cssHeight = bounds.height;
  pixelRatio = Math.min(window.devicePixelRatio || 1, 2);
  canvas.width = Math.round(cssWidth * pixelRatio);
  canvas.height = Math.round(cssHeight * pixelRatio);
  context.setTransform(pixelRatio, 0, 0, pixelRatio, 0, 0);
  draw();
}

function pointFromEvent(event) {
  const bounds = canvas.getBoundingClientRect();
  return { x: event.clientX - bounds.left, y: event.clientY - bounds.top };
}

function beginDrag(event) {
  const point = pointFromEvent(event);
  const layout = geometry();
  const hitRadius = layout.radius + 14;
  const distanceToCharge1 = Math.hypot(point.x - layout.charge1.x, point.y - layout.charge1.y);
  const distanceToCharge2 = Math.hypot(point.x - layout.charge2.x, point.y - layout.charge2.y);

  if (distanceToCharge1 > hitRadius && distanceToCharge2 > hitRadius) return;
  state.dragging = distanceToCharge1 <= distanceToCharge2 ? 1 : 2;
  state.pointerId = event.pointerId;
  canvas.setPointerCapture(event.pointerId);
  canvas.classList.add("dragging");
  event.preventDefault();
}

function dragCharge(event) {
  if (state.dragging === null || event.pointerId !== state.pointerId) return;
  const point = pointFromEvent(event);
  const layout = geometry();
  const proposedSeparation = state.dragging === 1
    ? 2 * (layout.centerX - point.x)
    : 2 * (point.x - layout.centerX);
  const fraction = clamp(
    (proposedSeparation - layout.minimumSeparation) / (layout.maximumSeparation - layout.minimumSeparation),
    0,
    1
  );
  const rawDistance = MIN_DISTANCE + fraction * (MAX_DISTANCE - MIN_DISTANCE);
  state.distance = clamp(
    Math.round(rawDistance / DISTANCE_STEP) * DISTANCE_STEP,
    MIN_DISTANCE,
    MAX_DISTANCE
  );
  syncOutputs(false);
  event.preventDefault();
}

function endDrag(event) {
  if (state.dragging === null || event.pointerId !== state.pointerId) return;
  if (canvas.hasPointerCapture(event.pointerId)) canvas.releasePointerCapture(event.pointerId);
  state.dragging = null;
  state.pointerId = null;
  canvas.classList.remove("dragging");
  announce("Distance updated.");
}

function adjustDistance(delta, prefix) {
  state.distance = clamp(
    Math.round((state.distance + delta) / DISTANCE_STEP) * DISTANCE_STEP,
    MIN_DISTANCE,
    MAX_DISTANCE
  );
  syncOutputs(true, prefix);
}

q1Input.addEventListener("input", () => {
  state.q1 = Number(q1Input.value);
  syncOutputs(false);
});
q1Input.addEventListener("change", () => announce("Charge one updated."));

q2Input.addEventListener("input", () => {
  state.q2 = Number(q2Input.value);
  syncOutputs(false);
});
q2Input.addEventListener("change", () => announce("Charge two updated."));

distanceInput.addEventListener("input", () => {
  state.distance = Number(distanceInput.value);
  syncOutputs(false);
});
distanceInput.addEventListener("change", () => announce("Distance updated."));

playPause.addEventListener("click", () => setRunning(!state.running, true));

resetButton.addEventListener("click", () => {
  state.q1 = INITIAL_STATE.q1;
  state.q2 = INITIAL_STATE.q2;
  state.distance = INITIAL_STATE.distance;
  state.phase = 0;
  syncOutputs(true, "Reset.");
});

canvas.addEventListener("pointerdown", beginDrag);
canvas.addEventListener("pointermove", dragCharge);
canvas.addEventListener("pointerup", endDrag);
canvas.addEventListener("pointercancel", endDrag);
canvas.addEventListener("lostpointercapture", () => {
  state.dragging = null;
  state.pointerId = null;
  canvas.classList.remove("dragging");
});

canvas.addEventListener("keydown", (event) => {
  if (event.key === "ArrowLeft" || event.key === "ArrowDown") {
    event.preventDefault();
    adjustDistance(-DISTANCE_STEP, "Distance decreased.");
  } else if (event.key === "ArrowRight" || event.key === "ArrowUp") {
    event.preventDefault();
    adjustDistance(DISTANCE_STEP, "Distance increased.");
  } else if (event.key === "Home") {
    event.preventDefault();
    state.distance = MIN_DISTANCE;
    syncOutputs(true, "Minimum distance selected.");
  } else if (event.key === "End") {
    event.preventDefault();
    state.distance = MAX_DISTANCE;
    syncOutputs(true, "Maximum distance selected.");
  }
});

document.addEventListener("visibilitychange", () => {
  if (document.hidden) stopAnimation();
  else startAnimation();
});

window.addEventListener("breadboard:themechange", () => {
  readPalette();
  draw();
});

reducedMotion.addEventListener("change", (event) => {
